class Counter {
  #value = 0;
  add() { this.#value++; }
  read() { return this.#value; }
}
const c = new Counter();
c.add();
console.log(c.read());

class Square {
  constructor(side) { this.side = side; }
  get area() { return this.side * this.side; }
}
console.log(new Square(3).area);

class Animal { speak() { return "sound"; } }
