class Animal { speak() { return "sound"; } }
class Dog extends Animal { speak() { return "woof"; } }
console.log(new Dog().speak());

const sounds = [
  { speak() { return "woof"; } },
  { speak() { return "meow"; } }
];
console.log(sounds.map(animal => animal.speak()).join(", "));

const bell = { ring() { return "ding"; } };
const bike = { bell, signal() { return this.bell.ring(); } };
console.log(bike.signal());

class Basket {
  prices = [];
  add(price) { this.prices.push(price); }
  total() { return this.prices.reduce((sum, price) => sum + price, 0); }
}
const basket = new Basket();
basket.add(3); basket.add(4);
console.log(basket.total());
